// Renders all stored jobs as an HTML table. ?status=SHORTLISTED filters.
const base = 'http://localhost:5678/webhook/job-hunt';
const wanted = String($('List Jobs Webhook').first().json.query?.status || '').toUpperCase();
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
// Rows discovered before the last Config & Profile update were analyzed against an older profile.
// Update this timestamp whenever the profile changes. Display only: stored rows are never modified.
const PROFILE_UPDATED_AT = '2026-09-29T21:08:30Z';
const isHistorical = (r) => Date.parse(r.discoveredAt || r.createdAt) < Date.parse(PROFILE_UPDATED_AT);
const STATUSES = ['DISCOVERED', 'ANALYZED', 'SHORTLISTED', 'REVIEW_REQUIRED', 'APPLIED', 'REJECTED', 'INTERVIEW', 'OFFER', 'IGNORED'];
const rows = $input.all().map((i) => i.json).filter((r) => r.jobKey && (!wanted || r.status === wanted))
  .sort((a, b) => (b.matchScore || 0) - (a.matchScore || 0));
const tabs = ['ALL', ...STATUSES].map((s) => `<a class="${(s === 'ALL' ? !wanted : wanted === s) ? 'on' : ''}" href="${base}${s === 'ALL' ? '' : '?status=' + s}">${s}</a>`).join('');
const trs = rows.map((r) => `<tr>
  <td><b>${esc(r.matchScore)}</b>${isHistorical(r) ? '<div class="m">historical</div>' : ''}</td>
  <td><a href="${base}/job?id=${r.id}">${esc(r.title)}</a><div class="m">${esc(r.company)}</div></td>
  <td>${esc(r.location)}${r.remote ? ' · remote' : ''}</td>
  <td>${esc(r.salaryRaw)}</td>
  <td><span class="s s-${esc(r.status)}">${esc(r.status)}</span></td>
  <td>${esc(r.source)}</td>
  <td>${esc(String(r.discoveredAt || '').slice(0, 10))}</td></tr>`).join('');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Job Tracker</title>
<style>body{font:14px system-ui;margin:24px;background:#fafafa;color:#222}table{border-collapse:collapse;width:100%;background:#fff}td,th{padding:8px;border-bottom:1px solid #eee;text-align:left;vertical-align:top}
.m{color:#777;font-size:12px}.tabs a{margin-right:8px;padding:4px 8px;border-radius:6px;text-decoration:none;color:#333;background:#eee;font-size:12px}.tabs a.on{background:#333;color:#fff}
.s{font-size:11px;padding:2px 6px;border-radius:4px;background:#eee}.s-SHORTLISTED{background:#dbeafe}.s-REVIEW_REQUIRED{background:#fed7aa}.s-APPLIED{background:#fef3c7}.s-INTERVIEW,.s-OFFER{background:#dcfce7}.s-REJECTED,.s-IGNORED{background:#f3f4f6;color:#888}
@media(prefers-color-scheme:dark){body{background:#111;color:#ddd}table{background:#1a1a1a}td,th{border-color:#2a2a2a}.tabs a,.s{background:#2a2a2a;color:#ddd}a{color:#8ab4f8}}</style></head>
<body><h2>Job Hunt Agent v2 — Tracker</h2><div class="tabs">${tabs}</div><p class="m">${rows.length} job(s)</p>
<table><tr><th>Match</th><th>Role</th><th>Location</th><th>Compensation</th><th>Status</th><th>Source</th><th>Found</th></tr>${trs}</table></body></html>`;
return [{ json: { html } }];

// Renders one job with its generated package and a status/notes form.
const base = 'http://localhost:5678/webhook/job-hunt';
const r = $input.first()?.json || {};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
if (!r.jobKey) return [{ json: { html: `<p>Job not found. <a href="${base}">Back</a></p>` } }];
// Rows discovered before the last Config & Profile update were analyzed against an older profile.
// Update this timestamp whenever the profile changes. Display only: stored rows are never modified.
const PROFILE_UPDATED_AT = '2026-09-29T21:08:30Z';
const isHistorical = (r) => Date.parse(r.discoveredAt || r.createdAt) < Date.parse(PROFILE_UPDATED_AT);
const historical = isHistorical(r);
const STATUSES = ['DISCOVERED', 'ANALYZED', 'SHORTLISTED', 'REVIEW_REQUIRED', 'APPLIED', 'REJECTED', 'INTERVIEW', 'OFFER', 'IGNORED'];
const list = (s) => String(s || '').split('\n').filter(Boolean).map((x) => `<li>${esc(x)}</li>`).join('') || '<li>—</li>';
const block = (title, text) => `<h3>${title}</h3>${text ? `<button onclick="navigator.clipboard.writeText(this.nextElementSibling.innerText)">Copy</button><pre>${esc(text)}</pre>` : '<p class="m">Not generated (only the top shortlisted jobs per run get a package).</p>'}`;
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(r.title)}</title>
<style>body{font:14px system-ui;margin:24px;max-width:900px;background:#fafafa;color:#222}pre{white-space:pre-wrap;background:#fff;border:1px solid #eee;padding:12px;border-radius:6px}.m{color:#777}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}@media(max-width:700px){.grid{grid-template-columns:1fr}}.warn{background:#fff7ed;border:1px solid #fed7aa;padding:8px;border-radius:6px;white-space:pre-wrap}
@media(prefers-color-scheme:dark){body{background:#111;color:#ddd}pre{background:#1a1a1a;border-color:#2a2a2a}.warn{background:#3a2a10;border-color:#7a5a20}a{color:#8ab4f8}}</style></head><body>
<p><a href="${base}">← all jobs</a></p>
<h2>${esc(r.title)}</h2><p><b>${esc(r.company)}</b> · ${esc(r.location)} · Remote: ${r.remote === true ? 'yes' : r.remote === false ? 'no' : 'unknown'} · ${esc(r.employmentType)}</p>
<p>Compensation: <b>${esc(r.salaryRaw)}</b> <span class="m">(${esc(r.salaryNote)})</span></p>
${historical ? '<p class="warn"><b>Historical analysis — generated with an older candidate profile. Match score and reasoning may be outdated.</b></p>' : ''}<p>Match: <b>${esc(r.matchScore)}</b> (${esc(r.matchLevel)}, ${esc(r.recommendation)}, confidence ${esc(r.confidence)}) <span class="m">${esc(r.scoreBreakdown)}</span></p>
<p>${r.applicationUrl ? `Apply: <a href="${esc(r.applicationUrl)}" target="_blank">${esc(r.applicationUrl)}</a><br>` : '<span class="m">No direct application link found in the posting.</span><br>'}Listing: <a href="${esc(r.sourceUrl)}" target="_blank">${esc(r.sourceUrl)}</a></p>
<form action="${base}/status" method="get"><input type="hidden" name="id" value="${r.id}">${r.status === 'REVIEW_REQUIRED' ? `<input type="hidden" name="system" value="${esc(String(r.notes || '').split('\n').filter((n) => /^(CHECK|GENERATION ERROR):/.test(n)).join('\n')).replace(/\n/g, '&#10;')}">` : ''}
Status: <select name="status">${STATUSES.map((s) => `<option ${s === r.status ? 'selected' : ''}>${s}</option>`).join('')}</select>
<input name="notes" size="50" placeholder="notes" value="${esc(String(r.notes || '').split('\n').filter((n) => !/^(CHECK|GENERATION ERROR):/.test(n)).join(' '))}"> <button>Save</button></form>
${historical ? '<details><summary><b>Historical AI output (older candidate profile)</b> — Why, Gaps, Matching skills, resume, cover letter, answers</summary>' : ''}${r.notes && /CHECK:|GENERATION ERROR/.test(r.notes) ? `<p class="warn">${esc(r.notes)}</p>` : ''}
<div class="grid"><div><h3>Why</h3><ul>${list(r.why)}</ul><h3>Matching skills</h3><ul>${list(r.matchingSkills)}</ul></div>
<div><h3>Gaps</h3><ul>${list(r.missingSkills)}${list(r.experienceGap)}</ul>${r.languageRequirement ? `<p>Language: ${esc(r.languageRequirement)}</p>` : ''}</div></div>
${block('Tailored resume (Markdown)', r.resume)}${block('Cover letter', r.coverLetter)}${block('Application answers', r.answers)}${historical ? '</details>' : ''}
<details><summary>Job description</summary><pre>${esc(r.description)}</pre></details>
<p class="m">You apply manually. Nothing is ever submitted automatically.</p></body></html>`;
return [{ json: { html } }];

const q = $('Update Status Webhook').first().json.query || {};
const STATUSES = ['DISCOVERED', 'ANALYZED', 'SHORTLISTED', 'REVIEW_REQUIRED', 'APPLIED', 'REJECTED', 'INTERVIEW', 'OFFER', 'IGNORED'];
const status = String(q.status || '').toUpperCase();
const id = Number(q.id);
if (!STATUSES.includes(status) || !Number.isInteger(id)) throw new Error(`Invalid status update (id=${q.id}, status=${q.status})`);
// REVIEW_REQUIRED keeps its system-written review reasons (CHECK: / GENERATION ERROR: lines, carried in the page's
// hidden "system" field) across manual saves. Every other status saves exactly as before.
const systemLines = status === 'REVIEW_REQUIRED'
  ? String(q.system || '').split(/\r?\n/).filter((l) => /^(CHECK|GENERATION ERROR):/.test(l)).slice(0, 40) : [];
const notes = [...systemLines, String(q.notes || '').slice(0, 2000)].filter(Boolean).join('\n');
return [{ json: { id, status, notes, statusUpdatedAt: new Date().toISOString() } }];

const id = $('Validate Status Update').first().json.id;
const url = `http://localhost:5678/webhook/job-hunt/job?id=${id}`;
return [{ json: { html: `<!doctype html><meta http-equiv="refresh" content="0;url=${url}"><a href="${url}">Saved — back to job</a>` } }];
